mapper.select:
SELECT
    --  应急事件办结率（stat_mon_evt_rpt），百分比的数值（但无％号），
    -- 如果total_rpt_count为0，返回100
    (
        SELECT ROUND(
            CASE
                WHEN IFNULL(SUM(total_rpt_count),0) = 0 THEN 100
                ELSE IFNULL(SUM(completed_count),0) / IFNULL(SUM(total_rpt_count),1) * 100
            END,
            2
        )
        FROM stat_mon_evt_rpt


                region_code = #{regionCode}


                AND stat_cycle = #{statCycle}


    ) AS completeRate,

    --  预警准确率（stat_early_warn_region）
    -- 用 已处理数（假设已处理说明预警准确） /总数
    (
        SELECT ROUND(
            CASE
                WHEN IFNULL(SUM(total_warn_count),0) = 0 THEN 100
                ELSE IFNULL(SUM(completed_count),0) / IFNULL(SUM(total_warn_count),1) * 100
            END,
            2
        )
        FROM stat_early_warn_region


                region_code = #{regionCode}


                AND stat_cycle = #{statCycle}


    ) AS earlyWarnAccRate,

    --  应急资源调用率（biz_emerg_res）
    (
        SELECT ROUND(
            CASE
                WHEN IFNULL(SUM(stock_qty),0) = 0 THEN 0
                ELSE IFNULL(SUM(dispatch_count),0) / IFNULL(SUM(stock_qty),1) * 100
            END,
            2
        )
        FROM biz_emerg_res


                region_code = #{regionCode}


                AND stat_cycle = #{statCycle}


    ) AS resUseRate,

    --  平均处置时长（stat_mon_evt_rpt）
    (
        SELECT ROUND(IFNULL(AVG(avg_handle_endure),0), 2)
        FROM stat_mon_evt_rpt


                region_code = #{regionCode}


                AND stat_cycle = #{statCycle}


    ) AS avgHandleEndure,

    --  风险整改率（biz_risk_hazard）
    (
        SELECT ROUND(
        CASE
            WHEN COUNT(1) = 0 THEN 100
            ELSE SUM(CASE WHEN warn_status IN ('2','3') THEN 1 ELSE 0 END) / COUNT(1) * 100
        END,
        2
        )
        FROM biz_risk_hazard


                region_code = #{regionCode}


                AND discover_time >= #{statCycleStartDate}
                AND discover_time < #{statCycleEndDate}



    ) AS riskRectifyRate
